-- Owner-authorized reversible publication hold, 2026-11-03.
-- Private archive retains original rows. No DELETE/TRUNCATE is performed.
set local lock_timeout = '5s';
set local statement_timeout = '45s';
alter table public.recipes add column rights_suspended boolean not null default false;
alter table public.recipes add column cover_image_usage_status text not null default 'rights_unknown'
  check (cover_image_usage_status in ('rights_unknown','rights_confirmed','placeholder_only','removal_requested'));
alter table public.recipes add column cover_image_permission_ref text;
alter table public.beans add column image_permission_ref text;
alter table public.roasted_products add column image_permission_ref text;
alter table public.bean_images add column image_permission_ref text;
alter table public.equipment_models add column image_permission_ref text;
alter table public.roasters add column logo_permission_ref text;

create table private.content_rights_holds (
  table_name text not null check (table_name in ('recipes','beans','equipment_models','roasters')),
  record_id uuid not null,
  original_values jsonb not null,
  replacement_values jsonb not null,
  active boolean not null default true,
  reason text not null default 'Owner-approved pending permission review, 2026-11-03',
  evidence_reference text,
  reviewed_at timestamptz,
  captured_at timestamptz not null default now(),
  primary key(table_name,record_id),
  check (active or (nullif(btrim(evidence_reference),'') is not null and reviewed_at is not null))
);
alter table private.content_rights_holds enable row level security;
revoke all on private.content_rights_holds from public,anon,authenticated;
comment on table private.content_rights_holds is 'Private, reversible content review archive. Never expose snapshots to app clients. Release individual records only after evidence review.';

-- Fail closed if a nonempty production catalog differs from the audited ID set.
do $$ begin
  if exists(select 1 from public.recipes where visibility='public') and (select md5(string_agg(id::text,',' order by id::text)) from public.recipes where visibility='public') <> '425c7a4515b2e3ef3f98926a6d0003b4' then raise exception 'AUDITED_RECIPES_SET_CHANGED'; end if;
  if exists(select 1 from public.beans where is_published and not requires_review) and (select md5(string_agg(id::text,',' order by id::text)) from public.beans where is_published and not requires_review) <> '2b1089a20bd0098b7b3683d574049285' then raise exception 'AUDITED_BEANS_SET_CHANGED'; end if;
  if exists(select 1 from public.equipment_models where not requires_review) and (select md5(string_agg(id::text,',' order by id::text)) from public.equipment_models where not requires_review) <> 'b430d513db6638449271bb735baaaca0' then raise exception 'AUDITED_EQUIPMENT_MODELS_SET_CHANGED'; end if;
  if exists(select 1 from public.roasters where not requires_review) and (select md5(string_agg(id::text,',' order by id::text)) from public.roasters where not requires_review) <> '60f2361e96c55ebd5388cbbec262e2fc' then raise exception 'AUDITED_ROASTERS_SET_CHANGED'; end if;
end $$;

insert into private.content_rights_holds(table_name,record_id,original_values,replacement_values)
select 'recipes',r.id,to_jsonb(r),'{"rights_suspended":true}'::jsonb from public.recipes r where visibility='public';
insert into private.content_rights_holds(table_name,record_id,original_values,replacement_values)
select 'beans',b.id,to_jsonb(b),jsonb_build_object('image_url',null,'image_source_url',null,'image_usage_status','placeholder_only','image_permission_ref',null,
 'description_en','Coffee for your brewing collection. Choose a brewing method and adjust your recipe to taste.',
 'description_ar','بن لمجموعتك وتجارب التحضير. اختر طريقة التحضير وعدّل وصفتك حسب المذاق.')
from public.beans b where is_published and not requires_review;
insert into private.content_rights_holds(table_name,record_id,original_values,replacement_values)
select 'equipment_models',e.id,to_jsonb(e),jsonb_build_object('image_url',null,'image_source_url',null,'image_usage_status','placeholder_only','image_permission_ref',null,'notes',null,
 'description','Coffee equipment. Check the manufacturer instructions for operation, capacity and compatibility.',
 'specifications',jsonb_build_object('catalog',jsonb_build_object('schema_version',1,'name_ar',coalesce(e.specifications->'catalog'->>'name_ar',e.name),
 'description_en','Coffee equipment. Check the manufacturer instructions for operation, capacity and compatibility.',
 'description_ar','أداة لتحضير القهوة. راجع تعليمات المصنع للتشغيل والسعة والتوافق.','images','[]'::jsonb,'facts','{}'::jsonb)))
from public.equipment_models e where not requires_review;
insert into private.content_rights_holds(table_name,record_id,original_values,replacement_values)
select 'roasters',r.id,to_jsonb(r),jsonb_build_object('logo_url',null,'logo_source_url',null,'logo_usage_status','placeholder_only','logo_permission_ref',null,
 'description_en','Coffee roaster. Visit its website for current products and availability.',
 'description_ar','محمصة قهوة. راجع موقعها للاطلاع على المنتجات المتوفرة حاليًا.')
from public.roasters r where not requires_review;

-- This trigger only reads a fixed private archive and rewrites the current row.
-- A definer is required because clients must never read the original snapshots.
-- It is not an RPC, cannot be called as a normal function and has no API EXECUTE grant.
-- Existing row-owner RLS and trust-field triggers still authorize all writes.
create function private.enforce_content_rights_hold() returns trigger
language plpgsql security definer set search_path = '' as $$
declare replacement jsonb;
begin
  select h.replacement_values into replacement from private.content_rights_holds h
    where h.table_name=tg_table_name and h.record_id=new.id and h.active;
  if found then new := jsonb_populate_record(new,replacement); end if;
  return new;
end $$;
revoke all on function private.enforce_content_rights_hold() from public,anon,authenticated;
do $$ declare t text; begin
 foreach t in array array['recipes','beans','equipment_models','roasters'] loop
  execute format('create trigger z_content_rights_hold before insert or update on public.%I for each row execute function private.enforce_content_rights_hold()',t);
 end loop;
end $$;

-- A member cannot self-approve publisher media or clear a publication suspension.
create function private.guard_content_permission_fields() returns trigger
language plpgsql security invoker set search_path = '' as $$
declare field text; prefix text; prior jsonb := case when tg_op='UPDATE' then to_jsonb(old) else '{}'::jsonb end; incoming jsonb := to_jsonb(new);
begin
 if current_user not in ('anon','authenticated') or (select private.has_role('admin')) then return new; end if;
 foreach field in array array['image_permission_ref','logo_permission_ref','cover_image_permission_ref'] loop
  if nullif(incoming->>field,'') is not null and incoming->field is distinct from prior->field then
   raise exception 'CONTENT_PERMISSION_REVIEW_REQUIRED' using errcode='42501';
  end if;
 end loop;
 -- Permission attaches to an exact asset. Keeping its reference while changing
 -- the URL, source or approval status must not approve another publisher image.
 foreach prefix in array array['image','logo','cover_image'] loop
  if nullif(incoming->>(prefix||'_permission_ref'),'') is not null and (
   incoming->(prefix||'_url') is distinct from prior->(prefix||'_url') or
   incoming->(prefix||'_source_url') is distinct from prior->(prefix||'_source_url') or
   incoming->(prefix||'_usage_status') is distinct from prior->(prefix||'_usage_status')) then
   raise exception 'CONTENT_PERMISSION_REVIEW_REQUIRED' using errcode='42501';
  end if;
 end loop;
 if tg_table_name='recipes' and (
    (coalesce((incoming->>'rights_suspended')::boolean,false) and tg_op='INSERT') or
    (tg_op='UPDATE' and incoming->'rights_suspended' is distinct from prior->'rights_suspended') or
    (incoming->>'cover_image_usage_status'='rights_confirmed' and incoming->'cover_image_usage_status' is distinct from prior->'cover_image_usage_status')) then
  raise exception 'CONTENT_PERMISSION_REVIEW_REQUIRED' using errcode='42501';
 end if;
 return new;
end $$;
revoke all on function private.guard_content_permission_fields() from public,anon,authenticated;
do $$ declare t text; begin
 foreach t in array array['recipes','beans','bean_images','roasted_products','equipment_models','roasters'] loop
  execute format('create trigger guard_content_permissions before insert or update on public.%I for each row execute function private.guard_content_permission_fields()',t);
 end loop;
end $$;

create policy "suspended recipes stay out of app reads" on public.recipes
as restrictive for select to anon,authenticated using (not rights_suspended);

-- The hold trigger applies only the archived replacement fields, preserving IDs,
-- foreign keys, saves, brewing history and every original recipe child record.
-- These rows' search documents are already hidden by the parent-recipe RLS.
-- Avoid thousands of redundant per-row index rebuilds during this atomic hold.
-- All authorization, rights and integrity triggers remain enabled.
alter table public.recipes disable trigger maintain_recipe_search_documents;
alter table public.beans disable trigger maintain_recipe_search_documents;
alter table public.roasters disable trigger maintain_recipe_search_documents;
update public.recipes r set rights_suspended=true from private.content_rights_holds h where h.table_name='recipes' and h.record_id=r.id;
update public.beans b set image_url=null from private.content_rights_holds h where h.table_name='beans' and h.record_id=b.id;
update public.equipment_models e set image_url=null from private.content_rights_holds h where h.table_name='equipment_models' and h.record_id=e.id;
update public.roasters r set logo_url=null from private.content_rights_holds h where h.table_name='roasters' and h.record_id=r.id;
alter table public.recipes enable trigger maintain_recipe_search_documents;
alter table public.beans enable trigger maintain_recipe_search_documents;
alter table public.roasters enable trigger maintain_recipe_search_documents;

